const res = $input.all()[0].json;
const text = (res.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n').trim();
const rows = $('Flatten Rows').all().map(i => i.json);
return [{ json: {
  run_id: $('Build Claude Context').all()[0].json.run_id,
  logged_at: new Date().toISOString(),
  kind: 'daily_commentary',
  model: res.model || ($env.CLAUDE_MODEL || 'claude-sonnet-5'),
  target_dates: rows.map(r => r.target_date).join(','),
  mean_DA_fraction: (rows.reduce((s,r)=>s+Number(r.DA_fraction),0)/rows.length).toFixed(3),
  commentary: text,
  input_tokens: res.usage?.input_tokens ?? '',
  output_tokens: res.usage?.output_tokens ?? ''
}}];
